const controls = $input.first().json;

const sources = {
  shopify: {
    source: 'fictional_shopify',
    snapshot_date: '2026-01-15',
    records: [
      { period: '2026-01-15T00:00:00Z', gross_revenue: 7000.00, new_customers: 70, order_count: 120, refund_count: 18, refunded_revenue: 1000.00 },
      { period: '2026-01-15T12:00:00Z', gross_revenue: 5000.00, new_customers: 50, order_count: 80, refund_count: 12, refunded_revenue: 800.00 }
    ]
  },
  meta_ads: {
    source: 'fictional_meta_ads',
    snapshot_date: '2026-01-15',
    records: [
      { campaign_id: 'demo-prospecting', spend: 5000.00, impressions: 150000, clicks: 250, frequency: 6.0, previous_period_spend: 2500.00 },
      { campaign_id: 'demo-retargeting', spend: 3000.00, impressions: 100000, clicks: 150, frequency: 6.0, previous_period_spend: 1500.00 }
    ]
  },
  klaviyo: {
    source: 'fictional_klaviyo',
    snapshot_date: '2026-01-15',
    records: [
      { campaign_id: 'demo-welcome-series', messages_sent: 2400, messages_delivered: 2350, attributed_orders: 36 },
      { campaign_id: 'demo-winback-series', messages_sent: 1600, messages_delivered: 1540, attributed_orders: 14 }
    ]
  },
  google_sheets: {
    source: 'fictional_google_sheets',
    snapshot_date: '2026-01-15',
    records: [
      { row_id: 'demo-storefront-traffic', sessions: 10000, owner: 'Operations', data_quality_status: 'verified' }
    ]
  }
};

return [{ json: { controls, sources } }];

const input = $input.first().json;
const { sources } = input;

const normalized = {
  commerce: sources.shopify.records.map((record) => ({
    occurred_at: record.period,
    revenue: Number(record.gross_revenue),
    new_customers: Number(record.new_customers),
    orders: Number(record.order_count),
    refunds: Number(record.refund_count),
    refunded_revenue: Number(record.refunded_revenue)
  })),
  advertising: sources.meta_ads.records.map((record) => ({
    campaign_id: record.campaign_id,
    ad_spend: Number(record.spend),
    impressions: Number(record.impressions),
    clicks: Number(record.clicks),
    creative_frequency: Number(record.frequency),
    previous_period_ad_spend: Number(record.previous_period_spend)
  })),
  lifecycle_marketing: sources.klaviyo.records.map((record) => ({
    campaign_id: record.campaign_id,
    messages_sent: Number(record.messages_sent),
    messages_delivered: Number(record.messages_delivered),
    attributed_orders: Number(record.attributed_orders)
  })),
  operations: sources.google_sheets.records.map((record) => ({
    row_id: record.row_id,
    sessions: Number(record.sessions),
    owner: record.owner,
    data_quality_status: record.data_quality_status
  }))
};

return [{ json: { controls: input.controls, snapshot_date: '2026-01-15', normalized } }];

const input = $input.first().json;
const { commerce, advertising, operations } = input.normalized;

const sum = (records, field) => records.reduce((total, record) => total + record[field], 0);
const totalImpressions = sum(advertising, 'impressions');
const weightedFrequency = totalImpressions === 0
  ? 0
  : advertising.reduce((total, record) => total + (record.creative_frequency * record.impressions), 0) / totalImpressions;

const raw_inputs = {
  revenue: sum(commerce, 'revenue'),
  ad_spend: sum(advertising, 'ad_spend'),
  new_customers: sum(commerce, 'new_customers'),
  orders: sum(commerce, 'orders'),
  sessions: sum(operations, 'sessions'),
  refunds: sum(commerce, 'refunds'),
  refunded_revenue: sum(commerce, 'refunded_revenue'),
  impressions: totalImpressions,
  clicks: sum(advertising, 'clicks'),
  creative_frequency: weightedFrequency,
  previous_period_ad_spend: sum(advertising, 'previous_period_ad_spend')
};

return [{ json: { controls: input.controls, snapshot_date: input.snapshot_date, raw_inputs } }];

const input = $input.first().json;

return [{
  json: {
    metric_snapshot: {
      id: '11111111-1111-4111-8111-111111111111',
      created_at: '2026-01-15T12:05:00Z',
